import 'package:flutter/material.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:lazerus_app/core/macros/sinks/lighting_target_sink.dart';
import 'package:lazerus_app/features/debug/application/debug_devices_controller.dart';
import 'package:lazerus_app/features/macros/presentation/node_modules/lighting_target/lighting_target_macro_editor_node_module.dart';
import 'package:lazerus_app/features/macros/presentation/node_modules/macro_editor_node_module.dart';
import 'package:lazerus_core/lazerus_core.dart';

void main() {
  testWidgets(
    'an imported placeholder lists only compatible devices and replaces itself',
    (tester) async {
      final node = _placeholderNode();
      MacroNode? replacement;
      final compatible = _device(
        id: 'device-brightness',
        name: 'Bright light',
        features: const <LightingFeature>[LightingFeature.brightness],
      );
      final incompatible = _device(
        id: 'device-power-only',
        name: 'Power-only light',
        features: const <LightingFeature>[LightingFeature.power],
      );
      final state = MacroEditorNodePresentationState(
        graph: MacroGraph(
          id: 'macro',
          name: 'Imported',
          nodes: <MacroNode>[node],
          edges: const <MacroEdge>[],
        ),
        enabled: true,
        devicesById: <String, DebugDevice>{
          compatible.appDeviceId: compatible,
          incompatible.appDeviceId: incompatible,
        },
        devices: <DebugDevice>[compatible, incompatible],
      );
      final nodeContext = MacroEditorNodeViewContext(
        node: node,
        state: state,
        replaceNode: (value) => replacement = value,
        removeNode: () {},
      );

      await tester.pumpWidget(
        MaterialApp(
          home: Builder(
            builder: (context) => Scaffold(
              body: LightingTargetMacroEditorNodeModule().buildInspector(
                context,
                nodeContext,
              ),
            ),
          ),
        ),
      );

      expect(find.text('Device placeholder 1'), findsOneWidget);
      await tester.tap(
        find.byKey(const Key('resolve-template-placeholder-target')),
      );
      await tester.pumpAndSettle();

      expect(find.text('Bright light'), findsOneWidget);
      expect(find.text('Power-only light'), findsNothing);

      await tester.tap(find.text('Bright light'));
      await tester.pumpAndSettle();

      expect(replacement, isNotNull);
      expect(replacement!.id, node.id);
      expect(
        replacement!.ports.map((port) => port.id),
        orderedEquals(node.ports.map((port) => port.id)),
      );
      expect(
        LightingTargetNodeConfiguration.fromNode(replacement!).targetId,
        compatible.appDeviceId,
      );
    },
  );
}

MacroNode _placeholderNode() {
  final configuration = LightingTargetNodeConfiguration(
    targetId: 'template-device:1',
    parameters: <MacroTargetParameter>[MacroTargetParameter.brightness],
  );
  return MacroNode(
    id: 'target',
    kind: lightingTargetSinkKind,
    displayName: 'Device placeholder 1',
    ports: configuration.portsForNode('target'),
    parameters: configuration.toNodeParameters(),
  );
}

DebugDevice _device({
  required String id,
  required String name,
  required List<LightingFeature> features,
}) => DebugDevice(
  appDeviceId: id,
  endpoint: TransportEndpoint(
    id: 'endpoint-$id',
    transport: TransportKind.ble,
    displayName: name,
  ),
  protocolId: 'test',
  matchConfidence: 100,
  matchReason: 'Test device',
  status: DebugDeviceConnectionStatus.connected,
  capabilities: DeviceCapabilities(
    features: <LightingFeature, FeatureCapability>{
      for (final feature in features)
        feature: FeatureCapability(
          availability: CapabilityAvailability.verified,
        ),
    },
  ),
);
